const texto = String($('Ignorar?').first().json.output || '');
return texto
  .split(/\n+/)
  .map(p => p.trim())
  .filter(p => p.length > 0)
  .map(text => ({ json: { text } }));

const final = {};
const mensagens = [];

for (const item of items) {
  const json = item.json;
  if (json.Messagem) mensagens.push(json.Messagem);
  for (const key in json) {
    if (key !== 'Messagem') final[key] = json[key];
  }
}

// Telefone só com dígitos, sem inventar o 9. O CRM compara por DDD + últimos 8 dígitos.
final.telefone = String(final.From || '').split('@')[0].replace(/\D/g, '');
final.Messagem = mensagens.join(', ');

return [{ json: final }];

// Intervalo aleatório entre envios: 2 a 7 minutos
const min = 120;
const max = 420;
return [{ json: { delay: Math.floor(Math.random() * (max - min + 1)) + min } }];

// Junta candidatos de Instagram: link do Google, links no site e palpites pelo nome/domínio.
const lead = $('Edit Fields').first().json;
const html = String($('Buscar site').first().json.html || '');
const norm = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const reservado = new Set(['p', 'explore', 'reel', 'reels', 'stories', 'accounts', 'tv', 'direct', 'share', 'sharer', 'about', 'legal', 'developer']);
const candidatos = [];
const add = (u, origem) => {
  u = String(u || '').replace(/\/+$/, '').toLowerCase();
  if (!u || reservado.has(u) || !/^[a-z0-9._]{3,30}$/.test(u) || candidatos.some(c => c.usuario === u)) return;
  candidatos.push({ usuario: u, origem });
};
add(lead.instagram_usuario, 'google');
for (const m of html.matchAll(/instagram\.com\/([A-Za-z0-9._]{3,30})/g)) add(m[1], 'site');

const generico = /^(clinica|odontologica|odontologia|odonto|estetica|consultorio|centro|instituto|espaco|studio|ltda|me|eireli|e)$/;
const conectivo = /^(de|da|do|das|dos|e)$/;
const palavras = norm(lead.Nome).replace(/[^a-z0-9 ]/g, ' ').split(/\s+/).filter(Boolean);
const corte = palavras.findIndex((p, i) => i > 0 && generico.test(p));
const principal = corte > 0 ? palavras.slice(0, corte) : palavras;
const dominio = (String(lead.Site || '').match(/^https?:\/\/(?:www\.)?([^\/:?#]+)/i) || [])[1] || '';
const raizDominio = dominio.split('.')[0];
if (raizDominio && !/^(sites|linktr|wa|api|bit|instagram|facebook|google|negocio|business)$/.test(raizDominio)) add(raizDominio, 'palpite');
add(principal.join(''), 'palpite');
add(principal.filter(p => !conectivo.test(p)).join(''), 'palpite');
add(palavras.join(''), 'palpite');

const confiavel = candidatos.some(c => c.origem !== 'palpite');
const busca = confiavel ? '' : String(lead.Nome || '').split(/\s+/).slice(0, 4).join(' ');
return [{ json: { candidatos: candidatos.slice(0, 5), dominio, busca } }];

// Junta o que foi coletado num dossiê curto para a IA e num resumo para o CRM.
const lead = $('Edit Fields').first().json;
const norm = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]/g, '');
const dias = d => { const t = Date.parse(d); return isNaN(t) ? null : Math.floor((Date.now() - t) / 86400000); };

// Instagram: escolhe o perfil certo entre os candidatos
let instagram = null;
try {
  const achar = $('Achar Instagram').first().json;
  const cands = achar.candidatos || [];
  const perfis = $('Buscar Instagram').all().map(i => i.json).filter(j => j && j.username);
  const generico = /^(clinica|odontologica|odontologia|odonto|estetica|consultorio|centro|instituto|espaco|studio|de|da|do|das|dos|e)$/;
  const tokens = String(lead.Nome || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9 ]/g, ' ')
    .split(/\s+/).filter(t => t.length >= 4 && !generico.test(t));
  const tel8 = String(lead.Telefone || '').replace(/\D/g, '').slice(-8);
  const cidade = norm(String(lead.Cidade || '').split(',')[0]);
  const raiz = String(achar.dominio || '').split('.')[0];
  const pesquisados = new Set($('Pesquisar Instagram').all().map(i => String(i.json.username || '').toLowerCase()).filter(Boolean));
  const existe = p => !p.error && (p.id || p.fullName || p.biography || p.followersCount != null || (p.latestPosts || []).length);
  const pontua = p => {
    const u = String(p.username).toLowerCase();
    const c = cands.find(x => x.usuario === u);
    if (c && c.origem !== 'palpite') return { p, pts: 100, origem: c.origem };
    // nome/bio/link do perfil real (o usuário em si não conta para palpites: seria circular)
    const texto = norm(`${p.fullName} ${p.biography} ${p.externalUrl}`);
    let pts = tokens.filter(t => texto.includes(norm(t))).length;
    const forte = (raiz && raiz.length >= 4 && texto.includes(norm(raiz))) || (tel8 && String(p.biography || '').replace(/\D/g, '').includes(tel8));
    if (forte) pts += 5;
    if (cidade && texto.includes(cidade)) pts += 1;
    if (pesquisados.has(u)) pts += 0.5 * tokens.filter(t => u.includes(norm(t))).length;
    return { p, pts, origem: pesquisados.has(u) ? 'pesquisa no Instagram' : 'palpite pelo nome/site' };
  };
  const ok = perfis.filter(existe).map(pontua).filter(r => r.pts >= 3);
  const melhor = ok.sort((a, b) => b.pts - a.pts)[0];
  if (melhor) {
    const p = melhor.p;
    const posts = (p.latestPosts || []).slice(0, 6).map(x => ({
      dias_atras: dias(x.timestamp), tipo: x.type || '', legenda: String(x.caption || '').replace(/\s+/g, ' ').slice(0, 220),
    }));
    instagram = {
      usuario: p.username, encontrado_por: melhor.origem, nome: p.fullName || '', bio: String(p.biography || '').slice(0, 300),
      seguidores: p.followersCount ?? null, categoria: p.businessCategoryName || '', link_bio: p.externalUrl || '',
      ultimo_post_dias: posts.length ? posts[0].dias_atras : null, posts,
    };
  }
} catch (e) {}

// Site
let site = null;
try {
  const html = String($('Buscar site').first().json.html || '');
  if (html.length > 200) {
    const ent = t => String(t).replace(/&#(\d+);/g, (_, n) => String.fromCharCode(n)).replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&[a-z]+;/g, ' ');
    const pega = re => ent((html.match(re) || [])[1] || '').replace(/\s+/g, ' ').trim();
    let texto = html.replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>|<noscript[\s\S]*?<\/noscript>/gi, ' ')
      .replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
    texto = ent(texto);
    site = { titulo: pega(/<title[^>]*>([\s\S]*?)<\/title>/i).slice(0, 150),
             descricao: pega(/<meta[^>]+name=["']description["'][^>]+content=["']([^"']*)/i).slice(0, 300),
             trecho: texto.slice(0, 1500) };
  }
} catch (e) {}

// Avaliações do Google
let avaliacoes = [];
try { avaliacoes = JSON.parse(lead.avaliacoes_recentes || '[]'); } catch (e) {}

// Biblioteca de Anúncios: só conta como "anuncia" se o anunciante bater com o nome ou o Instagram
let anuncios = { verificado: false, anuncia: null, exemplos: [] };
try {
  const itens = $('Buscar anúncios Meta').all().map(i => i.json).filter(j => j && !j.error);
  const alvo = [norm(lead.Nome), norm(instagram?.nome), norm(lead.instagram_usuario)].filter(s => s.length >= 4);
  const doLead = itens.filter(a => {
    const pg = norm(a.pageName || a.page_name || a.snapshot?.page_name);
    return pg && alvo.some(t => pg.includes(t) || t.includes(pg));
  });
  const rodou = $('Buscar anúncios Meta').all().length > 0 && !$('Buscar anúncios Meta').first().json.error;
  anuncios = {
    verificado: rodou,
    anuncia: rodou ? doLead.length > 0 : null,
    exemplos: doLead.slice(0, 3).map(a => String(a.snapshot?.body?.text || a.adContent || a.body || '').replace(/\s+/g, ' ').slice(0, 200)).filter(Boolean),
  };
} catch (e) {}

const linhas = [];
linhas.push(`GOOGLE: nota ${lead.Nota} com ${lead['Avaliações']} avaliações. Categoria: ${lead.Nicho}. Cidade: ${lead.Cidade}.`);
if (avaliacoes.length) linhas.push('AVALIAÇÕES RECENTES:\n' + avaliacoes.map(a => `- ${a.nota}★ ${a.texto}`).join('\n'));
if (instagram) {
  linhas.push(`INSTAGRAM @${instagram.usuario}: ${instagram.seguidores ?? '?'} seguidores. Bio: ${instagram.bio || '-'}. Link na bio: ${instagram.link_bio || '-'}.`);
  if (instagram.posts.length) linhas.push('POSTS RECENTES:\n' + instagram.posts.map(p => `- há ${p.dias_atras ?? '?'} dias (${p.tipo}): ${p.legenda || '(sem legenda)'}`).join('\n'));
} else linhas.push('INSTAGRAM: não encontrado.');
if (site) linhas.push(`SITE: ${site.titulo} | ${site.descricao}\nTrecho: ${site.trecho}`);
else linhas.push('SITE: não encontrado.');
linhas.push(!anuncios.verificado ? 'ANÚNCIOS NA META: não verificado.'
  : anuncios.anuncia ? 'ANÚNCIOS NA META: tem anúncios ativos. Exemplos: ' + (anuncios.exemplos.join(' | ') || '(sem texto)')
  : 'ANÚNCIOS NA META: nenhum anúncio ativo encontrado.');

return [{ json: {
  dossie_texto: linhas.join('\n\n'),
  instagram_url: instagram ? `https://www.instagram.com/${instagram.usuario}/` : null,
  anuncia_meta: anuncios.anuncia,
  enriquecimento: {
    coletado_em: new Date().toISOString(),
    instagram, site: site ? { titulo: site.titulo, descricao: site.descricao } : null,
    avaliacoes, anuncios,
  },
}, pairedItem: { item: 0 } }];

// Intervalo aleatório entre envios: 2 a 7 minutos
const min = 120;
const max = 420;
return [{ json: { delay: Math.floor(Math.random() * (max - min + 1)) + min } }];
